const input = $input.first().json;
const data = input.body || input;

const allInputs = $input.all();
console.log('✅ Agent 4: Received', allInputs.length, 'item(s)');
console.log('✅ Agent 4: Blog content length:', (data.blogContent || '').length);

if (allInputs.length !== 1) {
  console.error('⚠️ AGENT 4 ERROR: Expected 1 item, got', allInputs.length);
}

return [{
  json: {
    blogContent: data.blogContent,
    topic: data.topic,
    style: data.style,
    length: data.length,
    sources: data.sources || []
  }
}];

const ollamaResponse = $input.first().json;
const prepData = $("Build Edit Prompt").first().json;

let finalPost = ollamaResponse.response || '';

// Clean up if wrapped in markdown code blocks
if (finalPost.includes('```')) {
  const match = finalPost.match(/```(?:markdown)?\s*([\s\S]*?)```/);
  if (match) {
    finalPost = match[1].trim();
  }
}

// Ensure it starts with title
if (!/^#\s+/.test(finalPost)) {
  const titleMatch = finalPost.match(/^#\s+.+/m);
  if (titleMatch) {
    finalPost = finalPost.substring(finalPost.indexOf(titleMatch[0]));
  }
}

const wordCount = finalPost.split(/\s+/).length;
console.log('✅ Agent 4: Edited post', wordCount, 'words');

return [{
  json: {
    finalPost: finalPost,
    topic: prepData.topic,
    style: prepData.style,
    length: prepData.length,
    sources: prepData.sources,
    qualityScore: null,
    issuesFound: [],
    improvementsMade: []
  }
}];
